class ZoneCoverageAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)
        self._zone_rows = 4
        self._zone_cols = 4

    def _zone_of(self, r, c):
        return (r // self._zone_rows, c // self._zone_cols)

    def _uncovered_zones(self, game, grid, rows, cols):
        covered = set()
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell.is_revealed and not cell.is_mine:
                    covered.add(self._zone_of(r, c))
        num_zr = (rows + self._zone_rows - 1) // self._zone_rows
        num_zc = (cols + self._zone_cols - 1) // self._zone_cols
        all_zones = set()
        for zr in range(num_zr):
            for zc in range(num_zc):
                all_zones.add((zr, zc))
        return all_zones - covered

    def opening_action(self, game, grid, rows, cols):
        num_zr = (rows + self._zone_rows - 1) // self._zone_rows
        num_zc = (cols + self._zone_cols - 1) // self._zone_cols
        zr = num_zr // 2
        zc = num_zc // 2
        r = zr * self._zone_rows + self._zone_rows // 2
        c = zc * self._zone_cols + self._zone_cols // 2
        r = min(r, rows - 1)
        c = min(c, cols - 1)
        return ("reveal", r, c)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = game.get_config().rows
        cols = game.get_config().cols
        uncovered = self._uncovered_zones(game, grid, rows, cols)
        zone = self._zone_of(r, c)
        zone_bonus = 0.3 if zone in uncovered else 0.0
        return (p - zone_bonus, self._rng.random())

