class ExtendedCrossNeighborhood(Neighborhood):
    """Extended cross: all cells in the same row/column within 2 steps (orthogonal reach-2).
    Each numbered cell sees up to 8 neighbors along axes, giving rich directional clues
    that reward constraint reasoning while cascades propagate further along lines."""

    _OFFSETS = [
        (-2, 0), (-1, 0), (1, 0), (2, 0),
        (0, -2), (0, -1), (0, 1), (0, 2),
    ]

    def offsets(self) -> list[tuple[int, int]]:
        return self._OFFSETS

