class ExtendedCrossNeighborhoodAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        offsets = [(-2, 0), (-1, 0), (1, 0), (2, 0), (0, -2), (0, -1), (0, 1), (0, 2)]
        result = []
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result.append((nr, nc))
        return result

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        changed = True
        iterations = 0
        while changed and iterations < 10:
            changed = False
            iterations += 1
            for r in range(rows):
                for c in range(cols):
                    cell = grid[r][c]
                    if not cell.is_revealed or cell.adjacent_mines is None:
                        continue
                    clue = cell.adjacent_mines
                    nbrs = neighbors_of.get((r, c), [])
                    flagged = [(nr, nc) for nr, nc in nbrs if (nr, nc) in mine_set]
                    unknown = [(nr, nc) for nr, nc in nbrs if not grid[nr][nc].is_revealed and (nr, nc) not in mine_set]
                    remaining = clue - len(flagged)
                    if remaining < 0 or remaining > len(unknown):
                        continue
                    if remaining == 0 and unknown:
                        for pos in unknown:
                            if prob_map.get(pos, 0.5) != 0.0:
                                prob_map[pos] = 0.0
                                changed = True
                    if remaining == len(unknown) and unknown:
                        for pos in unknown:
                            if prob_map.get(pos, 0.5) != 1.0:
                                prob_map[pos] = 1.0
                                mine_set.add(pos)
                                changed = True
        return prob_map

class ParityMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        updated = dict(prob_map)

        revealed_clue_cells = []
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell.is_revealed and not cell.is_mine:
                    revealed_clue_cells.append((r, c))

        changed = True
        iterations = 0
        while changed and iterations < 8:
            changed = False
            iterations += 1
            for r, c in revealed_clue_cells:
                cell = grid[r][c]
                true_count = cell.adjacent_mines
                parity = true_count % 2
                nbrs = neighbors_of.get((r, c), [])
                flagged = sum(1 for nr, nc in nbrs if grid[nr][nc].is_flagged or (nr, nc) in mine_set)
                unknown = [(nr, nc) for nr, nc in nbrs if not grid[nr][nc].is_revealed and (nr, nc) not in mine_set and not grid[nr][nc].is_flagged]
                if not unknown:
                    continue
                remaining_mines = true_count - flagged
                if remaining_mines < 0:
                    remaining_mines = 0
                n_unknown = len(unknown)
                if remaining_mines == n_unknown:
                    for pos in unknown:
                        if updated.get(pos, 0.5) != 1.0:
                            updated[pos] = 1.0
                            changed = True
                elif remaining_mines == 0:
                    for pos in unknown:
                        if updated.get(pos, 0.5) != 0.0:
                            updated[pos] = 0.0
                            changed = True
                else:
                    prob_sum = sum(updated.get(pos, 0.5) for pos in unknown)
                    if n_unknown > 0:
                        base_prob = remaining_mines / n_unknown
                        for pos in unknown:
                            current = updated.get(pos, 0.5)
                            if parity == 0:
                                adjusted = current * 0.95 if current > base_prob else current * 1.05
                            else:
                                adjusted = current * 1.05 if current > base_prob else current * 0.95
                            adjusted = max(0.01, min(0.99, adjusted))
                            if abs(adjusted - current) > 0.001:
                                updated[pos] = adjusted
                                changed = True

        for r, c in revealed_clue_cells:
            cell = grid[r][c]
            true_count = cell.adjacent_mines
            nbrs1 = set(neighbors_of.get((r, c), []))
            for r2, c2 in revealed_clue_cells:
                if (r2, c2) == (r, c):
                    continue
                nbrs2 = set(neighbors_of.get((r2, c2), []))
                shared = nbrs1 & nbrs2
                if not shared:
                    continue
                only1 = nbrs1 - nbrs2
                only2 = nbrs2 - nbrs1
                def unknown_in(s):
                    return [pos for pos in s if not grid[pos[0]][pos[1]].is_revealed and pos not in mine_set and not grid[pos[0]][pos[1]].is_flagged]
                u_shared = unknown_in(shared)
                u_only1 = unknown_in(only1)
                u_only2 = unknown_in(only2)
                flagged1 = sum(1 for pos in nbrs1 if grid[pos[0]][pos[1]].is_flagged or pos in mine_set)
                flagged2 = sum(1 for pos in nbrs2 if grid[pos[0]][pos[1]].is_flagged or pos in mine_set)
                rem1 = max(0, true_count - flagged1)
                rem2 = max(0, grid[r2][c2].adjacent_mines - flagged2)
                if len(u_only1) == 0 and u_shared:
                    mines_in_shared = rem1
                    if mines_in_shared == len(u_shared):
                        for pos in u_shared:
                            updated[pos] = 1.0
                    elif mines_in_shared == 0:
                        for pos in u_shared:
                            updated[pos] = 0.0
                if len(u_only2) == 0 and u_shared:
                    mines_in_shared = rem2
                    if mines_in_shared == len(u_shared):
                        for pos in u_shared:
                            updated[pos] = 1.0
                    elif mines_in_shared == 0:
                        for pos in u_shared:
                            updated[pos] = 0.0

        return updated

class Radius2MooreAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        return game.board.neighbors(r, c)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        nbrs = neighbors_of.get((r, c), [])
        suspected_count = sum(
            1 for nr, nc in nbrs
            if (nr, nc) in mine_set or prob_map.get((nr, nc), 0.0) >= 0.5
        )
        safe_count = sum(
            1 for nr, nc in nbrs
            if prob_map.get((nr, nc), 0.5) < 0.15
        )
        return (p - 0.02 * safe_count + 0.01 * suspected_count, -safe_count, self._rng.random())

