class HexZoneCoverageAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        return list(game.board.neighbors(r, c))

    def _uncovered_zones(self, game, grid, rows, cols):
        zone_rows = 4
        zone_cols = 4
        num_zr = (rows + zone_rows - 1) // zone_rows
        num_zc = (cols + zone_cols - 1) // zone_cols
        uncovered = set()
        for zr in range(num_zr):
            for zc in range(num_zc):
                r_start = zr * zone_rows
                r_end = min(r_start + zone_rows, rows)
                c_start = zc * zone_cols
                c_end = min(c_start + zone_cols, cols)
                has_revealed = False
                has_safe = False
                for rr in range(r_start, r_end):
                    for cc in range(c_start, c_end):
                        cell = grid[rr][cc]
                        if not cell.is_mine:
                            has_safe = True
                            if cell.is_revealed:
                                has_revealed = True
                if has_safe and not has_revealed:
                    uncovered.add((zr, zc))
        return uncovered

    def _zone_of(self, r, c):
        return (r // 4, c // 4)

    def opening_action(self, game, grid, rows, cols):
        center_r = rows // 2
        center_c = cols // 2
        zone_rows = 4
        zone_cols = 4
        num_zr = (rows + zone_rows - 1) // zone_rows
        num_zc = (cols + zone_cols - 1) // zone_cols
        candidates = []
        for zr in range(num_zr):
            for zc in range(num_zc):
                r_mid = zr * zone_rows + zone_rows // 2
                c_mid = zc * zone_cols + zone_cols // 2
                r_mid = min(r_mid, rows - 1)
                c_mid = min(c_mid, cols - 1)
                candidates.append((r_mid, c_mid))
        if candidates:
            best = min(candidates, key=lambda rc: (abs(rc[0] - center_r) + abs(rc[1] - center_c)))
            return ("reveal", best[0], best[1])
        return ("reveal", center_r, center_c)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        rows = game.get_config().rows
        cols = game.get_config().cols
        p = prob_map.get(pos, 0.5)
        uncovered = self._uncovered_zones(game, grid, rows, cols)
        zone = self._zone_of(r, c)
        zone_bonus = 0.15 if zone in uncovered else 0.0
        adjusted_p = max(0.0, p - zone_bonus)
        suspected = sum(
            1
            for nr, nc in neighbors_of.get((r, c), [])
            if (nr, nc) in mine_set or prob_map.get((nr, nc), 0.0) >= 0.5
        )
        return (adjusted_p, -len(uncovered), suspected, self._rng.random())

class DriftingMinesFlagFirstAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        drift_prob = 0.30
        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            cell = grid[r][c]
            if cell.is_revealed or cell.is_flagged:
                adjusted[pos] = p
                continue
            neighbor_mine_probs = [
                prob_map.get((nr, nc), 0.0)
                for nr, nc in neighbors_of.get(pos, [])
                if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged
            ]
            drift_in = 1.0 - (1.0 - drift_prob) ** len(neighbor_mine_probs) if neighbor_mine_probs else 0.0
            blended = p * (1.0 - drift_prob) + (1.0 - p) * drift_in * sum(neighbor_mine_probs) / max(len(neighbor_mine_probs), 1)
            adjusted[pos] = min(max(blended, 0.0), 1.0)
        return adjusted

