class ZoneFirstMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)
        self._zone_size = 4
        self._zone_clear_quota = 0.75
        self._zone_win_quota = 0.60

    def _zone_progress(self, game, grid, rows, cols):
        zs = self._zone_size
        zone_rows = (rows + zs - 1) // zs
        zone_cols = (cols + zs - 1) // zs
        progress = {}
        for zr in range(zone_rows):
            for zc in range(zone_cols):
                r_start = zr * zs
                r_end = min(r_start + zs, rows)
                c_start = zc * zs
                c_end = min(c_start + zs, cols)
                safe_total = 0
                safe_revealed = 0
                for r in range(r_start, r_end):
                    for c in range(c_start, c_end):
                        cell = grid[r][c]
                        if not cell.is_mine:
                            safe_total += 1
                            if cell.is_revealed:
                                safe_revealed += 1
                if safe_total == 0:
                    frac = 1.0
                else:
                    frac = safe_revealed / safe_total
                progress[(zr, zc)] = (frac, safe_total, safe_revealed)
        return progress

    def _cell_zone(self, r, c):
        return (r // self._zone_size, c // self._zone_size)

    def _zone_priority_score(self, frac):
        if frac >= self._zone_clear_quota:
            return 0.0
        gap = self._zone_clear_quota - frac
        return 1.0 - gap

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        zone_progress = self._zone_progress(game, grid, rows, cols)
        zr, zc = self._cell_zone(r, c)
        frac, safe_total, safe_revealed = zone_progress.get((zr, zc), (0.0, 0, 0))
        if frac >= self._zone_clear_quota:
            zone_bonus = -0.1
        else:
            zone_bonus = self._zone_priority_score(frac) * 0.3
        adjusted_p = p - zone_bonus
        return (adjusted_p, self._rng.random())

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        zone_progress = self._zone_progress(game, grid, rows, cols)
        zs = self._zone_size
        zone_rows = (rows + zs - 1) // zs
        zone_cols = (cols + zs - 1) // zs
        total_zones = zone_rows * zone_cols
        cleared = sum(1 for (frac, st, sr) in zone_progress.values() if frac >= self._zone_clear_quota)
        needed = int(self._zone_win_quota * total_zones) + 1
        still_needed = max(0, needed - cleared)
        if still_needed == 0:
            return prob_map
        incomplete_zones = {k for k, (frac, st, sr) in zone_progress.items() if frac < self._zone_clear_quota}
        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            zkey = self._cell_zone(r, c)
            if zkey in incomplete_zones:
                frac = zone_progress[zkey][0]
                gap = self._zone_clear_quota - frac
                boost = gap * 0.15
                adjusted[pos] = max(0.0, p - boost)
            else:
                adjusted[pos] = p
        return adjusted

class ParityNeighborhoodMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        total_mines = game.get_config().mine_count

        unrevealed = [
            (r, c)
            for r in range(rows)
            for c in range(cols)
            if not grid[r][c].is_revealed and not grid[r][c].is_flagged and (r, c) not in mine_set
        ]

        if not unrevealed:
            return prob_map

        cell_index = {pos: i for i, pos in enumerate(unrevealed)}
        n = len(unrevealed)

        equations = []
        parities = []

        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                nbrs = game.board.neighbors(r, c)
                unknown_nbrs = [
                    pos for pos in nbrs
                    if not grid[pos[0]][pos[1]].is_revealed
                    and not grid[pos[0]][pos[1]].is_flagged
                    and pos not in mine_set
                ]
                if not unknown_nbrs:
                    continue
                flagged_count = sum(
                    1 for pos in nbrs
                    if grid[pos[0]][pos[1]].is_flagged or pos in mine_set
                )
                true_count = cell.adjacent_mines
                remaining = true_count - flagged_count
                parity_bit = remaining % 2
                row_vec = [0] * n
                for pos in unknown_nbrs:
                    if pos in cell_index:
                        row_vec[cell_index[pos]] = 1
                equations.append(row_vec)
                parities.append(parity_bit)

        if not equations:
            return prob_map

        m = len(equations)
        mat = [equations[i] + [parities[i]] for i in range(m)]

        pivot_cols = []
        pivot_row = 0
        for col in range(n):
            found = -1
            for row in range(pivot_row, m):
                if mat[row][col] == 1:
                    found = row
                    break
            if found == -1:
                continue
            mat[pivot_row], mat[found] = mat[found], mat[pivot_row]
            for row in range(m):
                if row != pivot_row and mat[row][col] == 1:
                    mat[row] = [(mat[row][j] ^ mat[pivot_row][j]) for j in range(n + 1)]
            pivot_cols.append((pivot_row, col))
            pivot_row += 1

        forced_mine = set()
        forced_safe = set()

        for pr, pc in pivot_cols:
            row = mat[pr]
            active = [j for j in range(n) if row[j] == 1]
            rhs = row[n]
            if len(active) == 1:
                pos = unrevealed[active[0]]
                if rhs == 1:
                    forced_mine.add(pos)
                else:
                    forced_safe.add(pos)

        new_prob_map = dict(prob_map)

        flagged_total = sum(
            1 for r in range(rows) for c in range(cols)
            if grid[r][c].is_flagged
        ) + len(mine_set)
        remaining_mines = total_mines - flagged_total
        free_cells = n - len(forced_mine) - len(forced_safe)
        base_prob = remaining_mines / max(n, 1)
        if free_cells > 0:
            adjusted_remaining = remaining_mines - len(forced_mine)
            base_prob = max(0.0, min(1.0, adjusted_remaining / free_cells))

        for pos in unrevealed:
            if pos in forced_mine:
                new_prob_map[pos] = 1.0
            elif pos in forced_safe:
                new_prob_map[pos] = 0.0
            elif pos not in new_prob_map:
                new_prob_map[pos] = base_prob

        return new_prob_map

class TelegraphedMinesAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        telegraphed = set()
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if cell.is_flagged and not cell.is_revealed:
                    telegraphed.add((r, c))
        for pos in telegraphed:
            prob_map[pos] = 1.0
            mine_set.add(pos)
        for pos in telegraphed:
            r, c = pos
            nbrs = neighbors_of.get(pos, [])
            for nr, nc in nbrs:
                ncell = game.get_cell(nr, nc)
                if not ncell.is_revealed and (nr, nc) not in mine_set:
                    flagged_nbrs = sum(
                        1 for xr, xc in neighbors_of.get((nr, nc), [])
                        if (xr, xc) in mine_set
                    )
                    clue_nbrs = []
                    for xr, xc in neighbors_of.get((nr, nc), []):
                        xcell = game.get_cell(xr, xc)
                        if xcell.is_revealed and xcell.adjacent_mines is not None:
                            clue_nbrs.append(((xr, xc), xcell.adjacent_mines))
                    for (xr, xc), clue in clue_nbrs:
                        unrevealed_nbrs = [
                            (yr, yc) for yr, yc in neighbors_of.get((xr, xc), [])
                            if not game.get_cell(yr, yc).is_revealed
                        ]
                        mines_around = sum(
                            1 for yr, yc in neighbors_of.get((xr, xc), [])
                            if (yr, yc) in mine_set
                        )
                        remaining_mines = clue - mines_around
                        remaining_unknown = [
                            (yr, yc) for yr, yc in unrevealed_nbrs
                            if (yr, yc) not in mine_set
                        ]
                        if remaining_mines <= 0 and (nr, nc) in remaining_unknown:
                            prob_map[(nr, nc)] = 0.0
                            break
                        if len(remaining_unknown) > 0 and remaining_mines == len(remaining_unknown):
                            prob_map[(nr, nc)] = 1.0
                            mine_set.add((nr, nc))
                            break
        return prob_map

class Radius2MooreCountMinesAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        refined = dict(prob_map)
        changed = True
        iterations = 0
        while changed and iterations < 5:
            changed = False
            iterations += 1
            revealed_numbered = [
                (r, c)
                for r in range(rows)
                for c in range(cols)
                if grid[r][c].is_revealed and not grid[r][c].is_mine
                and grid[r][c].adjacent_mines > 0
            ]
            for r, c in revealed_numbered:
                clue = grid[r][c].adjacent_mines
                nbrs = neighbors_of.get((r, c), [])
                unknown = [p for p in nbrs if not grid[p[0]][p[1]].is_revealed and p not in mine_set]
                flagged_count = sum(1 for p in nbrs if grid[p[0]][p[1]].is_flagged or p in mine_set)
                remaining = clue - flagged_count
                if remaining < 0:
                    remaining = 0
                if not unknown:
                    continue
                if remaining == 0:
                    for p in unknown:
                        if refined.get(p, 0.5) > 0.01:
                            refined[p] = 0.0
                            changed = True
                elif remaining == len(unknown):
                    for p in unknown:
                        if refined.get(p, 0.5) < 0.99:
                            refined[p] = 1.0
                            changed = True
                else:
                    base_prob = remaining / len(unknown)
                    for p in unknown:
                        old = refined.get(p, 0.5)
                        blended = 0.6 * old + 0.4 * base_prob
                        if abs(blended - old) > 0.02:
                            refined[p] = blended
                            changed = True
        return refined

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        nbrs = neighbors_of.get((r, c), [])
        constrained_by = sum(
            1
            for nr, nc in nbrs
            if grid[nr][nc].is_revealed and grid[nr][nc].adjacent_mines > 0
        )
        safe_neighbors = sum(
            1
            for nr, nc in nbrs
            if not grid[nr][nc].is_revealed
            and (nr, nc) not in mine_set
            and prob_map.get((nr, nc), 0.5) < 0.2
        )
        return (p, -constrained_by, -safe_neighbors, self._rng.random())
